const results = await Promise.allSettled([
  tools.exec_command({cmd:"pwd && git status --short && git remote -v && rg --files -g AGENTS.md -g composer.json -g composer.lock -g '.github/workflows/*' -g 'renovate*' -g '.renovate*'","workdir":"/Users/ab/Projects/peq","max_output_tokens":6000}),
  tools.exec_command({cmd:"cat /Users/ab/.agents/skills/find-docs/SKILL.md","max_output_tokens":5000}),
  tools.exec_command({cmd:"gh repo view k-kinzal/peq --json nameWithOwner,defaultBranchRef,url && gh run list --repo k-kinzal/peq --branch main --limit 20 --json databaseId,name,event,headSha,status,conclusion,createdAt,url && gh pr list --repo k-kinzal/peq --state open --limit 100 --json number,title,author,headRefName,baseRefName,mergeable,mergeStateStatus,isDraft,statusCheckRollup,url","workdir":"/Users/ab/Projects/peq","max_output_tokens":14000})
]); results.forEach((r,i)=>text({i,...r}));
text(ALL_TOOLS.filter(x=>/search/.test(x.name) && /tool/i.test(x.description)).map(x=>({name:x.name,description:x.description.slice(0,500)})));

